import React, { useState } from 'react';
import API from "../api/axios";
import { Mail, Lock, UserPlus, ArrowRight, X, ArrowLeft, ShieldCheck } from 'lucide-react';
import { useNavigate } from "react-router-dom";
const EntryCard = ({ isOpen, onClose }) => {
  const [isFlipped, setIsFlipped] = useState(false);
const navigate = useNavigate();
const [email, setEmail] = useState("");
const [password, setPassword] = useState("");
/*const handleLoginClick = () => {
  navigate("/dashboard");
};*/
const [error, setError] = useState("");
const handleLoginClick = async () => {
  if (!email || !password) {
    setError("Please fill email and password");
    return;
  }

  setError(""); // clear previous error

  try {
    const res = await API.post("/auth/login", {
      email,
      password,
    });

    localStorage.setItem("token", res.data.token);
    navigate("/dashboard");

  } catch (err) {
    setError("Invalid email or password");
    console.log(err);
  }
};
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md p-4">

      {/* Container that handles the Slide-Up animation */}
      <div className="flip-container w-full max-w-[400px] h-[580px] animate-slide-up">

        {/* Container that handles the 3D Flip */}
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          {/* --- FRONT SIDE: SIGN IN --- */}
          <div className="flip-front bg-[#FDFAD8] border-4 border-[#47510B] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-8 flex flex-col justify-between">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2 bg-[#47510B] px-3 py-1 rounded-full">
                <ShieldCheck size={14} className="text-[#CAD23C]" />
                <span className="text-[10px] font-black text-[#FDFAD8] uppercase tracking-widest">Secure Entry</span>
              </div>
              <button onClick={onClose} className="hover:rotate-90 transition-transform text-[#47510B]">
                <X size={30} />
              </button>
            </div>

            <div className="mt-6">
              <h2 className="text-4xl font-black text-[#47510B] uppercase tracking-tighter leading-none">welcome<br/>Back!</h2>
            </div>

            <div className="space-y-4">
              <div className="relative">
                <Mail className="absolute left-4 top-4 text-[#47510B]/30" size={18} />
                <input
  type="email"
  value={email}
  onChange={(e) => setEmail(e.target.value)}
  placeholder="EMAIL ADDRESS"
  className="w-full bg-white border-2 border-[#47510B] p-4 pl-12 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30 transition-all"
/>
              </div>
              <div className="relative">
                <Lock className="absolute left-4 top-4 text-[#47510B]/30" size={18} />
              <input
  type="password"
  value={password}
  onChange={(e) => setPassword(e.target.value)}
  placeholder="••••••••"
  className="w-full bg-white border-2 border-[#47510B] p-4 pl-12 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30 transition-all"
/>
{error && (
  <p className="text-[#AB1717] text-xs font-bold ml-2">
    {error}
  </p>
)}
              </div>
              <button
  onClick={handleLoginClick}
  className="w-full bg-[#47510B] text-[#CAD23C] font-black p-5 rounded-2xl flex items-center justify-center gap-3 shadow-[0_6px_0_0_#2A3106] active:translate-y-1 active:shadow-none transition-all uppercase text-xl italic"
>
  Access Dashboard <ArrowRight size={30} />
</button>
            </div>

            <div className="text-center pb-2">
              <button 
                onClick={() => setIsFlipped(true)} 
                className="text-[#47510B] font-black text-[15px] tracking-widest uppercase opacity-60 hover:opacity-100 transition-opacity"
              >
                No account? <span className="underline decoration-2 underline-offset-4 text-[#AB1717]">Join the Tribe</span>
              </button>
            </div>
          </div>

          {/* --- BACK SIDE: SIGN UP --- */}
<div className="flip-back bg-[#FFB6A9] border-4 border-[#AB1717] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-7 flex flex-col h-full">

  {/* TOP BAR - Kept your effects */}
  <div className="flex justify-between items-center mb-4">
     <button onClick={() => setIsFlipped(false)} className="flex items-center gap-2 text-[#47510B] font-black text-[16px] tracking-widest uppercase hover:scale-105 transition-transform">
      <ArrowLeft size={24} /> Back
    </button>
    <button onClick={onClose} className="text-[#AB1717] hover:rotate-90 transition-transform"><X size={30} /></button>
  </div>

  <div className="mb-4">
    <h2 className="text-4xl font-black text-[#AB1717] uppercase tracking-tighter leading-none">New<br/>Registry</h2>
    <div className="h-1 w-12 bg-[#AB1717] mt-2" />
  </div>

  {/* SIGN-UP FIELDS - Corrected with Scroll and High-Visibility Inputs */}
  <div className="flex-1 overflow-y-auto pr-2 space-y-3 custom-scrollbar mb-4">
    <div className="space-y-1">
      <label className="text-[15px] font-black text-[#AB1717] uppercase ml-1 opacity-70">Full_Name</label>
      <input type="text" placeholder="NAME_ENTRY" className="w-full p-3 bg-[#FDFAD8] rounded-xl border-2 border-transparent focus:border-[#47510B] outline-none font-black uppercase text-xs text-[#AB1717] placeholder-[#AB1717]/30 transition-all" />
    </div>

    <div className="space-y-1">
      <label className="text-[15px] font-black text-[#AB1717] uppercase ml-1 opacity-70">Email</label>
      <input type="email" placeholder="EMAIL_Address" className="w-full p-3 bg-[#FDFAD8] rounded-xl border-2 border-transparent focus:border-[#47510B] outline-none font-black uppercase text-xs text-[#AB1717] placeholder-[#AB1717]/30 transition-all" />
    </div>

    <div className="space-y-1">
      <label className="text-[15px] font-black text-[#AB1717] uppercase ml-1 opacity-70">Phone</label>
      <input type="tel" placeholder="+00 000 000" className="w-full p-3 bg-[#FDFAD8] rounded-xl border-2 border-transparent focus:border-[#47510B] outline-none font-black uppercase text-xs text-[#AB1717] placeholder-[#AB1717]/30 transition-all" />
    </div>

    <div className="space-y-1">
      <label className="text-[15px] font-black text-[#AB1717] uppercase ml-1 opacity-70">Residence</label>
